<template>
  <div class="mt-5">
    <form class="">
      <div class="mb-3">
        <label for="username" class="form-label">{{
          tm("form.username")
        }}</label>
        <input
          type="text"
          class="form-control"
          id="username"
          v-model="userName"
          ref="usernameInput"
        />
      </div>
      <div class="mb-3">
        <label for="exampleInputPassword1" class="form-label">{{
          tm("form.password")
        }}</label>
        <input
          type="password"
          class="form-control"
          id="exampleInputPassword1"
          v-model="password"
          ref="passwordInput"
        />
      </div>
      <div class="mb-3 form-check">
        <input type="checkbox" class="form-check-input" id="exampleCheck1" />
        <label class="form-check-label" for="exampleCheck1">Check me out</label>
      </div>
      <div class="d-flex justify-content-between">
        <button
          @click="loginUser(userName, password)"
          type="button"
          class="btn btn-primary"
        >
          {{ tm("header.login") }}
        </button>
        <button
          @click.prevent="headToProfilePage('SignForm')"
          type="button"
          class="btn btn-warning"
        >
          {{ tm("header.signin") }}
        </button>
      </div>
    </form>
  </div>
</template>

<script setup>
import router from "@/router";
import { useUsersStore } from "@/stores/users";
import { ref } from "vue";
import { useI18n } from "vue-i18n";
const { tm } = useI18n();
const users = useUsersStore();
const userName = ref("");
const password = ref("");
const usernameInput = ref(null);
const passwordInput = ref(null);

function headToProfilePage(pageName) {
  users.switchPage(pageName);
  router.push("/profile");
}
async function loginUser() {
  const result = await users.login(userName.value, password.value);
  if (result.process) {
    router.push("/profile");
  } else {
    alert(result.message);
  }
  userName.value = "";
  password.value = "";
}
</script>

<style scoped>
@media (max-width: 767px) {
  form {
    max-width: 90%;
    margin: auto;
  }
}
@media (min-width: 767px) {
  form {
    max-width: 50%;
    margin: auto;
  }
}
</style>
