import { defineStore } from "pinia";
import axios from "axios";
export const useUsersStore = defineStore("users", {
  state: () => {
    return {
      userLoginStatus: false,
      currentUser: null,
      page: "",
      usersList: [],
    };
  },
  getters: {},
  actions: {
    switchPage(pageName) {
      this.page = pageName;
    },
    initializeAuth() {
      try {
        const storedUser = localStorage.getItem("storedUser");
        if (storedUser) {
          this.currentUser = JSON.parse(storedUser);
          this.userLoginStatus = true;
          this.page = "ProfileUser"; // إضافة تلقائية للصفحة
        } else {
          this.page = "LogForm";
        }
      } catch (error) {
        console.error("Auth initialization error:", error);
        localStorage.removeItem("storedUser");
        this.currentUser = null;
        this.userLoginStatus = false;
        this.page = "LogForm";
      }
    },
    async register(userData) {
      if (
        userData.username.length > 0 &&
        userData.email.length > 0 &&
        userData.password.length > 0
      ) {
        const check = await axios.get(
          `https://online-store-api-production-80ff.up.railway.app/users?email=${userData.email}`
        );
        if (check.data.length > 0) {
          return {
            message: "email is used",
            process: false,
          };
        } else {
          const res = await axios.post(
            "https://online-store-api-production-80ff.up.railway.app/users",
            userData
          );
          this.switchPage("ProfileUser");
          this.userLoginStatus = true;
          this.currentUser = res.data;
          localStorage.setItem("storedUser", JSON.stringify(this.currentUser));
          return {
            message: "success",
            process: true,
          };
        }
      } else {
        return {
          message: "fill in all fields",
          process: false,
        };
      }
    },
    async login(userName, password) {
      const check = await axios.get(
        `https://online-store-api-production-80ff.up.railway.app/users?username=${userName}&password=${password}`
      );
      if (check.data.length > 0) {
        this.switchPage("ProfileUser");
        this.userLoginStatus = true;
        this.currentUser = check.data[0];
        localStorage.setItem("storedUser", JSON.stringify(this.currentUser));
        console.log(this.currentUser);

        return {
          message: "success",
          process: true,
        };
      } else {
        return {
          message: "try again",
          process: false,
        };
      }
    },
    logout() {
      this.currentUser = null;
      localStorage.removeItem("storedUser");

      console.log(this.currentUser);

      this.userLoginStatus = false;
      this.switchPage("LogForm");
    },
  },
});
