<template>
  <div>
    <div v-if="cart.bill.length > 0" class="bill">
      <table class="table">
        <thead>
          <tr>
            <th scope="col">#</th>
            <th scope="col">item</th>
            <th scope="col">quantity</th>
            <th scope="col">price</th>
            <th scope="col">remove</th>
          </tr>
        </thead>
        <tbody>
          <tr v-for="item in cart.bill" :key="item.id">
            <th scope="row">{{ i++ }}</th>
            <td>{{ item.name[locale] }}</td>
            <td>{{ item.quantity }}</td>
            <td>{{ item.price }}</td>
            <td @click="removeItem(item.id)" role="button" class="text-primary">
              remove
            </td>
          </tr>
          <tr>
            <th scope="row">#</th>
            <td>totall</td>
            <td class="fw-bold">{{ cart.totallQuantity }}</td>
            <td class="fw-bold">{{ cart.totallPrice }} $</td>
          </tr>
        </tbody>
      </table>
      <div>checkout</div>
    </div>
    <div v-else>
      <p>your basket is empty</p>
    </div>
  </div>
</template>

<script setup>
import { useCartStore } from "@/stores/cart";
import { useI18n } from "vue-i18n";
const { locale } = useI18n();
const cart = useCartStore();
var i = 1;
function removeItem(id) {
  if (confirm("Are you sure you want to remove this item?")) {
    cart.removeItem(id);
  }
}
</script>
